#include <cstdio>
#include <vector>

struct Node {
    int val;
    Node* next;
    Node(int v) : val(v), next(nullptr) {}
};

int main() {
    int n, k;
    scanf("%d %d", &n, &k);
    Node dummy(0);
    Node* tail = &dummy;
    for (int i = 0; i < n; ++i) {
        int v;
        scanf("%d", &v);
        tail->next = new Node(v);
        tail = tail->next;
    }

    Node* fast = &dummy;
    Node* slow = &dummy;
    for (int i = 0; i < k; ++i) fast = fast->next;
    while (fast->next) { fast = fast->next; slow = slow->next; }
    Node* toDel = slow->next;
    slow->next = toDel->next;
    delete toDel;

    bool first = true;
    for (Node* p = dummy.next; p; p = p->next) {
        if (!first) printf(" ");
        printf("%d", p->val);
        first = false;
    }
    printf("\n");
    return 0;
}
